@'
import re

_ITEM_RE = re.compile(r"^(-?\d+)(?:\s*-\s*(-?\d+))?$")


def parse_range(spec: str) -> list[int]:
    """Expand a comma separated range spec such as "1-3,5" into [1, 2, 3, 5].

    Each item is either a single number ("5") or an inclusive range ("1-3").
    Blank items are skipped, so "" and " , " both yield [].
    """
    result: list[int] = []
    if not spec:
        return result
    for item in spec.split(","):
        item = item.strip()
        if not item:
            continue
        match = _ITEM_RE.match(item)
        if match is None:
            raise ValueError(f"invalid range item: {item!r}")
        start = int(match.group(1))
        end = match.group(2)
        if end is None:
            result.append(start)
        else:
            result.extend(range(start, int(end) + 1))
    return result
'@ | Set-Content -Encoding utf8 src\ranges.py; Get-Content src\ranges.py

