@'
def mean(xs):
    return sum(xs) / len(xs) if xs else 0.0

def median(xs):
    if not xs:
        return None
    ordered = sorted(xs)
    n = len(ordered)
    mid = n // 2
    if n % 2 == 1:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2
'@ | Set-Content -Path src\stats.py -Encoding utf8NoBOM

